param([string]$SitePath = (Join-Path $env:USERPROFILE "Downloads\Central-IPTV-Premium-site\site"))
$ErrorActionPreference = "Stop"
$dest = (Resolve-Path -LiteralPath $SitePath).Path
$publisher = Join-Path $dest "Publicar-Painel.ps1"
if (-not (Test-Path -LiteralPath $publisher)) { throw "Informe a pasta original do site publicado usando -SitePath." }
$config = Get-Content -LiteralPath (Join-Path $dest "wrangler.jsonc") -Raw | ConvertFrom-Json
if ($config.d1_databases[0].database_id -eq "SUBSTITUIR_PELO_ID_DO_BANCO") { throw "Essa nao e a pasta do site publicado. Informe a pasta original com -SitePath." }
$files = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("")) | ConvertFrom-Json
foreach ($file in $files) {
    if ($file.path -like "migrations/*") {
        $target = Join-Path $dest $file.path
        if (Test-Path -LiteralPath $target) {
            $existing = [Convert]::ToBase64String([IO.File]::ReadAllBytes($target))
            if ($existing -ne $file.content) { throw "A migracao ja existe com conteudo diferente. Nenhum arquivo foi alterado. Consulte o suporte." }
        }
    }
}
$stamp = Get-Date -Format "yyyyMMdd-HHmmssfff"
foreach ($file in $files) {
    $target = Join-Path $dest $file.path
    if (Test-Path -LiteralPath $target) { Copy-Item -LiteralPath $target -Destination ($target + ".backup-" + $stamp) }
    [void][IO.Directory]::CreateDirectory((Split-Path $target -Parent))
    [IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($file.content))
}
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $publisher -ConectarDominio
if ($LASTEXITCODE -ne 0) { throw "Publicacao nao concluida. Confira a mensagem acima e execute novamente." }
Write-Host "Site atualizado: exclusao individual, multipla ou total e filtro por status." -ForegroundColor Green
Write-Host "A versao publicada, os cadastros e as credenciais existentes foram preservados." -ForegroundColor Green
